import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.7R1OEGYz.js";const k=JSON.parse('{"title":"Previewing a page the agent is building","description":"","frontmatter":{},"headers":[],"relativePath":"preview.md","filePath":"preview.md","lastUpdated":1786051954000}'),n={name:"preview.md"};function h(o,e,r,d,p,l){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="previewing-a-page-the-agent-is-building" tabindex="-1">Previewing a page the agent is building <a class="header-anchor" href="#previewing-a-page-the-agent-is-building" aria-label="Permalink to &quot;Previewing a page the agent is building&quot;">​</a></h1><p>An agent can serve a page from its own session pod and open it in the integrated browser. Nothing is published anywhere: the page never leaves the session, and the browser reaches it directly by pod address.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Start a server on one of the allowed ports, then point the browser at it. The session&#39;s own address is in <code>AGENTHUB_POD_IP</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./site</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>browser_navigate  http://$AGENTHUB_POD_IP:8000</span></span></code></pre></div><p>That is the whole flow. A real dev server works just as well, which is usually what you want because you keep hot reload:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5173</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Bind to 0.0.0.0</p><p>Dev servers that default to <code>localhost</code> are unreachable from the browser pod. Vite needs <code>--host</code>, Next.js <code>-H 0.0.0.0</code>, Python&#39;s <code>http.server</code> already binds everywhere.</p></div><h2 id="allowed-ports" tabindex="-1">Allowed ports <a class="header-anchor" href="#allowed-ports" aria-label="Permalink to &quot;Allowed ports&quot;">​</a></h2><p>Session pods deny all traffic by default, so only these ports are opened, and only between the browser and its own session:</p><table tabindex="0"><thead><tr><th>Port</th><th>Typical use</th></tr></thead><tbody><tr><td>3000</td><td>Next.js, Create React App</td></tr><tr><td>4173</td><td>Vite preview</td></tr><tr><td>5173</td><td>Vite dev server</td></tr><tr><td>8000</td><td><code>python -m http.server</code></td></tr><tr><td>8080</td><td>Anything generic</td></tr></tbody></table><p>Change them with <code>browser.previewPorts</code>, or set it to <code>[]</code> to switch the feature off:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">browser</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  previewPorts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5173</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The rules are created per browser lease and removed with it, so nothing outlives the session — and no other session, or anything else in the cluster, can reach that server.</p><h2 id="what-this-is-not" tabindex="-1">What this is not <a class="header-anchor" href="#what-this-is-not" aria-label="Permalink to &quot;What this is not&quot;">​</a></h2><p>The preview lives and dies with the session. It is for looking at what the agent is building, not for hosting. If you want a page to outlive the session, have the agent write it to the session&#39;s files and download it from there, or publish it somewhere you control.</p><p>Serving agent-generated HTML from the hub&#39;s own domain would put it on the same origin as the app, where it could read tokens and session data — which is exactly why the preview stays inside the pod network.</p>`,18)])])}const g=s(n,[["render",h]]);export{k as __pageData,g as default};
